/* Guided arrival: no health data, passwords or identity details are stored. */
window.NeoArrival=(()=>{
 const steps=[{target:'.nav-community',title:'Sua comunidade',text:'Seu portal de interações e conversas. Aqui você também encontra os materiais da Biblioteca.'},{target:'.home-quick-add',title:'Cada registro conta',text:'Toque no + para registrar seu peso e acompanhar sua evolução.'},{target:'.home-dose-shortcut',title:'Conheça a calculadora',text:'Em Dose, explore cálculos de volume e marcações para aprendizado. Ela não define uma prescrição.'},{target:'#nav [data-go=registros]',title:'Todo o seu processo',text:'Em Registros, organize todo o seu processo: peso, medidas, diário, fotos e aplicações.'},{target:'#nav [data-go=loja]',title:'Conheça a loja',text:'Na Loja, disponibilizamos a compra de protocolos. Confira os detalhes e as condições de cada produto.'},{target:'#communityIcon',title:'Converse com a equipe',text:'No botão Atendimento, você conversa diretamente com a nossa equipe, em um atendimento privado.'}];
 let owner='',pending=false,index=0,eligible=false,focus=null,showAgain=true,saving=false,savePreference=null;
 const key=id=>'neo-arrival-seen:'+id;
 function remove(){document.querySelector('[data-arrival]')?.remove();document.querySelectorAll('.arrival-target').forEach(el=>el.classList.remove('arrival-target'));}
 function arm(id,explicit=false){if(owner!==id){remove();owner=id;index=0;pending=false;}if(!id)return;let seen=false;try{seen=sessionStorage.getItem(key(id))==='1'}catch{}if(explicit||!seen){index=0;pending=true;}}
 function finish(){pending=false;try{if(owner)sessionStorage.setItem(key(owner),'1')}catch{}remove();focus?.focus?.({preventScroll:true});document.dispatchEvent(new window.Event('neo-arrival-finished'));}
 function position(){const root=document.querySelector('[data-arrival]');if(!root)return;const panel=root.querySelector('.arrival-panel'),v=window.visualViewport,w=v?.width||document.documentElement.clientWidth||window.innerWidth,h=v?.height||window.innerHeight,left=v?.offsetLeft||0,top=v?.offsetTop||0;panel.style.boxSizing='border-box';panel.style.width=Math.min(340,w-24)+'px';panel.style.maxHeight=Math.max(100,h-24)+'px';panel.style.left=(left+w/2)+'px';panel.style.transform='translateX(-50%)';const target=steps[index]?document.querySelector(steps[index].target):null,ph=panel.getBoundingClientRect().height||230;if(!target){panel.style.top=(top+Math.max(12,(h-ph)/2))+'px';return;}let r=target.getBoundingClientRect();if(target.matches('.nav-community')){const circle=target.querySelector('svg')?.getBoundingClientRect();if(circle){const t=Math.min(r.top,circle.top-10),l=Math.min(r.left,circle.left-8),right=Math.max(r.right??r.left+r.width,(circle.right??circle.left+circle.width)+8),bottom=Math.max(r.bottom,circle.bottom+8);r={top:t,left:l,right,bottom,width:right-l,height:bottom-t};}else r={...r,top:r.top-22,height:r.height+22};}const hole=root.querySelector('.arrival-spot');if(hole){const x=Math.max(left+4,r.left-6),right=Math.min(left+w-4,(r.right??r.left+r.width)+6);hole.style.cssText=`left:${x}px;top:${Math.max(top+4,r.top-6)}px;width:${Math.max(0,right-x)}px;height:${r.height+12}px`;}const preferred=r.bottom+ph+30<top+h?r.bottom+18:r.top-ph-18;panel.style.top=Math.max(top+12,Math.min(top+h-ph-12,preferred))+'px';}
 function sync(show,enabled=showAgain){eligible=show;showAgain=enabled;if(!enabled&&!saving)pending=false;if(!show||!pending||!owner){remove();return;}if(index>=steps.length){if(!document.querySelector('[data-arrival]')){const root=document.createElement('div');root.dataset.arrival='';root.className='arrival-overlay arrival-choice';root.innerHTML='<section class="arrival-panel" role="dialog" aria-modal="true" aria-labelledby="arrivalTitle"><span class="arrival-count">Tudo pronto</span><h2 id="arrivalTitle">Quer ver este guia no próximo login?</h2><p>Você escolhe se quer rever estas dicas ao entrar.</p><div class="arrival-choice-actions"><button class="primary full" type="button" data-arrival-preference="true">Sim, mostrar novamente</button><button class="secondary full" type="button" data-arrival-preference="false">Não, não mostrar mais</button></div><p data-arrival-status role="status"></p></section>';document.body.append(root);position();root.querySelector('button').focus();}return;}const target=document.querySelector(steps[index].target);if(!target){remove();return;}target.classList.add('arrival-target');if(document.querySelector('[data-arrival]')){position();return;}focus=document.activeElement;target.classList.add('arrival-target');target.scrollIntoView?.({block:'center',behavior:'instant'});const root=document.createElement('div');root.dataset.arrival='';root.className='arrival-overlay';const step=steps[index];root.innerHTML=`<div class="arrival-spot" aria-hidden="true"></div><section class="arrival-panel" role="dialog" aria-modal="true" aria-labelledby="arrivalTitle" aria-describedby="arrivalText"><span class="arrival-count">${index+1} de ${steps.length}</span><h2 id="arrivalTitle">${step.title}</h2><p id="arrivalText">${step.text}</p><button type="button" class="primary full" data-arrival-next>Entendi</button></section>`;document.body.append(root);position();root.querySelector('button').focus({preventScroll:true});}
 document.addEventListener('click',async e=>{const choice=e.target.closest('[data-arrival-preference]');if(choice){if(saving)return;const account=owner,enabled=choice.dataset.arrivalPreference==='true';saving=true;const root=choice.closest('[data-arrival]');root.querySelectorAll('button').forEach(b=>b.disabled=true);root.querySelector('[data-arrival-status]').textContent='Salvando sua escolha…';try{if(!savePreference)throw Error('not_configured');await savePreference(enabled);if(account!==owner)return;showAgain=enabled;finish();}catch{if(account===owner&&root.isConnected){root.querySelector('[data-arrival-status]').textContent='Não foi possível salvar. Tente novamente.';root.querySelectorAll('button').forEach(b=>b.disabled=false);}}finally{if(account===owner)saving=false;}return;}if(saving||!e.target.closest('[data-arrival-next]'))return;remove();index++;sync(eligible);});
 document.addEventListener('keydown',e=>{if(!document.querySelector('[data-arrival]'))return;if(e.key==='Tab'){const buttons=Array.from(document.querySelectorAll('[data-arrival] button:not([disabled])'));if(buttons.length){e.preventDefault();let i=buttons.indexOf(document.activeElement);buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length].focus();}}if(e.key==='Escape'){e.preventDefault();if(!saving)finish();}});
 window.visualViewport?.addEventListener('resize',position);window.visualViewport?.addEventListener('scroll',position);window.addEventListener('resize',position);window.addEventListener('scroll',position,true);
 return {arm,sync,configure(options){savePreference=options.savePreference;},reset(){remove();owner='';pending=false;index=0;showAgain=true;saving=false;},finish};
})();
